<?php $pageTitle='My faculty profile';?>
<div class="fp-page"><header class="fp-heading"><div><p class="fp-eyebrow">Faculty / Invigilator</p><h1>Profile &amp; availability</h1><p>Your employee record and examination availability.</p></div></header><?php require __DIR__.'/alerts.php';?>
<div class="fp-two-column"><section class="fp-card"><p class="fp-eyebrow"><?= e($faculty['employee_id']) ?></p><h2><?= e($faculty['name']) ?></h2><dl class="fp-profile-facts"><?php foreach(['designation'=>'Designation','school_name'=>'School','department_name'=>'Department','email'=>'Email','phone'=>'Phone'] as $field=>$label):?><div><dt><?= e($label) ?></dt><dd><?= e($faculty[$field]??'Not recorded') ?></dd></div><?php endforeach;?></dl><p class="fp-muted">Ask your coordinator to correct employee details.</p><a href="<?= e(url('faculty-panel/duties')) ?>">View my assigned duties →</a></section>
<section class="fp-card"><h2>Change password</h2><form method="post" class="fp-form" action="<?= e(url('faculty-panel/profile')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="password"><label>Current password<input type="password" name="current_password" autocomplete="current-password" required></label><label>New password<input type="password" name="password" minlength="12" autocomplete="new-password" required></label><label>Confirm new password<input type="password" name="password_confirmation" minlength="12" autocomplete="new-password" required></label><small>Use at least 12 characters.</small><button class="fp-button">Change password</button></form></section></div>
<section class="fp-card fp-section"><h2>Request availability change</h2><p>Requests go to the invigilation coordinator. Existing duties remain assigned until a replacement is approved.</p><form method="post" class="fp-form fp-form-grid" action="<?= e(url('faculty-panel/profile')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="availability"><label>Date<input type="date" name="exam_date" min="<?= e(date('Y-m-d')) ?>" required></label><label>Examination / shift<select name="shift_id" required><option value="">Choose a shift</option><?php foreach($shifts as $shift):?><option value="<?= (int)$shift['id'] ?>"><?= e($shift['cycle_name'].' · '.$shift['name'].' ('.$shift['start_date'].'–'.$shift['end_date'].')') ?></option><?php endforeach;?></select></label><label>Availability<select name="availability"><option value="unavailable">Unavailable</option><option value="available">Available</option><option value="preferred">Preferred</option></select></label><label>Reason<textarea name="reason" maxlength="1000" required></textarea></label><button class="fp-button" <?= !$shifts?'disabled':'' ?>>Send availability request</button></form><?php if(!$shifts):?><p>No upcoming published examination shifts are available for requests.</p><?php endif;?></section>
<section class="fp-section"><h2>My availability requests</h2><div class="fp-request-list"><?php foreach($availability as $item):?><article class="fp-card"><div class="fp-card-top"><strong><?= e($item['exam_date'].' · '.$item['shift_name']) ?></strong><span class="fp-status"><?= e(ucfirst($item['status'])) ?></span></div><p><?= e(ucfirst($item['availability']).' · '.$item['reason']) ?></p></article><?php endforeach;?><?php if(!$availability):?><div class="fp-empty">No availability requests submitted.</div><?php endif;?></div></section></div>
